def total(values):
    """Compute the sum of numeric values, ignoring None.

    Zeros and negative numbers are included. If there are no numeric
    values (for example an empty list or only None), returns 0.
    """
    numeric_values = [value for value in values if isinstance(value, (int, float))]
    if not numeric_values:
        return 0
    return sum(numeric_values)

